import re

from moler.exceptions import ParsingDone
from moler.exceptions import CommandFailure
from ta_moler.cmd.egate.genericepcsim import GenericEPCSIMCommand


class MmeFakePagingStop(GenericEPCSIMCommand):
    """Mme Fake Paging Stop command class."""

    def __init__(self, connection, enbs, session_id, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Mme fake paging stop command.

        :param connection: moler connection to device, terminal when command is executed.
        :param enbs: enb ids.
        :param session_id: session id.
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(MmeFakePagingStop, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.enbs = enbs
        self.session_id = session_id
        self.options = options
        self.ret_required = False

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"mme_fake_paging_stop enbs={self.enbs} session_id={self.session_id}"
        if self.options:
            cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_error(line)
            except ParsingDone:
                pass
        return super(MmeFakePagingStop, self).on_new_line(line, is_full_line)

    # Example line: 15:50:32.973 ERR: MME-1: Paging session (2) does not exist
    # Example line: Error: eNB-2 is not configured
    _re_error = re.compile(r'(Error|ERR): (?P<ERROR>.*)')

    def _parse_error(self, line):
        if self._regex_helper.search(self._re_error, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group('ERROR')))
            raise ParsingDone


COMMAND_OUTPUT = """
EGATE> mme_fake_paging_stop enbs=1 session_id=1

EGATE>"""

COMMAND_KWARGS = {'enbs': 1, 'session_id': 1}

COMMAND_RESULT = {}


